mapper.select:
WITH RECURSIVE , start_node (node_id) AS (
SELECT mb.member_id FROM member mb WHERE mb.node_id = #{startId} SELECT CAST(#{startId} AS text)
), hidden (member_id) AS (
SELECT m.method_id::text FROM analysis_method m JOIN analysis_symbol o ON o.revision_id = m.revision_id AND o.symbol_id = m.owner_symbol_id WHERE m.revision_id = #{revisionId} AND o.layer IN #{layer} AND m.method_id NOT IN (SELECT sn.node_id FROM start_node sn)
SELECT CAST(NULL AS text) WHERE FALSE
), walk (depth, src, dst, relation_type, conf) AS ( SELECT 1, r.from_id::text, COALESCE(r.to_id, 'T:' || r.to_external)::text, r.relation_type::text , FROM analysis_relation r WHERE r.revision_id = #{revisionId} AND r.relation_type IN #{type}
AND r.to_kind = 'TABLE' AND r.to_external = #{tableName} AND r.to_id IN (SELECT sn.node_id FROM start_node sn)
AND NOT EXISTS (SELECT 1 FROM hidden h WHERE h.member_id = r.from_id)
AND r.from_id IN (SELECT sn.node_id FROM start_node sn) AND (r.to_id IS NOT NULL OR (r.to_kind = 'TABLE' AND r.to_external IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM hidden h WHERE h.member_id = r.to_id)
UNION SELECT w.depth + 1, r.from_id::text, COALESCE(r.to_id, 'T:' || r.to_external)::text, r.relation_type::text , FROM walk w JOIN analysis_relation r ON r.revision_id = #{revisionId}
AND r.to_id = w.src AND r.from_id = w.dst
AND r.relation_type IN #{type} WHERE w.depth < #{depth}
AND NOT EXISTS (SELECT 1 FROM hidden h WHERE h.member_id = r.from_id)
AND (r.to_id IS NOT NULL OR (r.to_kind = 'TABLE' AND r.to_external IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM hidden h WHERE h.member_id = r.to_id)
) -- 서로를 부르는 메소드가 있으면 같은 선이 깊이를 바꿔 가며 다시 나온다. 가장 얕은 것 하나만 남긴다. SELECT MIN(w.depth) AS "depth" , w.src AS "from" , w.dst AS "to" , w.relation_type AS "type" , AS "confidence" FROM walk w GROUP BY w.src, w.dst, w.relation_type ORDER BY MIN(w.depth), w.src, w.dst LIMIT #{limit}

SELECT string_agg(c.content, E'\n' ORDER BY c.chunk_no)
  FROM rag_document d
  JOIN rag_chunk c ON c.doc_seq = d.doc_seq
 WHERE d.revision_id = #{revisionId}
   AND d.ref_kind = #{refKind}
   AND d.doc_type = #{docType}
   AND d.ref_id = #{refId}

SELECT 
  FROM analysis_mapper mp
  JOIN analysis_file f ON f.file_id = mp.file_id
 WHERE mp.revision_id = #{revisionId}
   AND mp.mapper_id = #{mapperId}
